-- Kits sans rattachement a une REGION, hors entrepots deja identifies.
-- Situation au 2026-11-06, Excel V2 et selection administrateur revision 14.
-- Affectations resolues par le dashboard a cette date. Regenerer apres modification.
WITH selected AS (
SELECT a.serial_number,a.product_reference,a.product_name,a.crm_flag,a.crm_owner_client_number,a.in_crm,a.crm_status status,CASE WHEN a.crm_status='DEPLOYED' THEN coalesce(prior.holder_id,a.crm_holder_agent_number,CASE WHEN l.nb_deployments=1 THEN l.last_agent_before_first_deployment END) ELSE coalesce(a.crm_holder_agent_number,CASE WHEN l.current_holder_category='AGENT' AND replace(l.current_status,'IN_STOCK','INSTOCK')=a.crm_status THEN l.current_holder_id END) END holder_id,CASE WHEN a.crm_status='DEPLOYED' THEN CASE WHEN prior.holder_id IS NOT NULL THEN prior.holder_name WHEN a.crm_holder_agent_number IS NULL AND l.nb_deployments=1 THEN l.last_agent_name_before_first_deployment END ELSE coalesce(a.crm_holder_name,l.current_holder_name) END holder_name,CASE WHEN prior.holder_id=(CASE WHEN a.crm_status='DEPLOYED' THEN coalesce(prior.holder_id,a.crm_holder_agent_number,CASE WHEN l.nb_deployments=1 THEN l.last_agent_before_first_deployment END) ELSE coalesce(a.crm_holder_agent_number,CASE WHEN l.current_holder_category='AGENT' AND replace(l.current_status,'IN_STOCK','INSTOCK')=a.crm_status THEN l.current_holder_id END) END) THEN distribution.holder_id ELSE NULL END routing_shop_id FROM bi_schema.dim_asset a LEFT JOIN bi_schema.fct_asset_lifecycle l ON l.serial_number=a.serial_number LEFT JOIN (SELECT DISTINCT ON(p.serial_number) p.serial_number,p.holder_id,p.holder_name FROM bi_schema.fct_asset_holding_periods p JOIN bi_schema.dim_asset asset USING(serial_number) LEFT JOIN bi_schema.fct_asset_lifecycle life USING(serial_number)  WHERE p.holder_category='AGENT' AND p.holder_id IS NOT NULL AND p.start_at<=(CASE WHEN asset.crm_status='DEPLOYED' THEN coalesce(life.last_deployed_at,asset.deploy_date AT TIME ZONE 'Africa/Douala') ELSE (('2026-11-06'::date+1)::timestamp AT TIME ZONE 'Africa/Douala') END) ORDER BY p.serial_number,p.start_at DESC,p.period_no DESC) prior ON prior.serial_number=a.serial_number LEFT JOIN (SELECT DISTINCT ON(p.serial_number) p.serial_number,p.holder_id FROM bi_schema.fct_asset_holding_periods p JOIN bi_schema.dim_asset asset USING(serial_number) LEFT JOIN bi_schema.fct_asset_lifecycle life USING(serial_number)  WHERE p.holder_category='AGENT' AND p.holder_role='POINT RELAIS' AND p.start_at<=(CASE WHEN asset.crm_status='DEPLOYED' THEN coalesce(life.last_deployed_at,asset.deploy_date AT TIME ZONE 'Africa/Douala') ELSE (('2026-11-06'::date+1)::timestamp AT TIME ZONE 'Africa/Douala') END) ORDER BY p.serial_number,p.start_at DESC,p.period_no DESC) distribution ON distribution.serial_number=a.serial_number  WHERE '2026-11-06'::date IS NOT NULL AND (a.crm_status IN ('DEPLOYED','INSTOCK','DEFECTIVE') AND EXISTS (SELECT 1 FROM bi_schema.fct_asset_holding_periods history WHERE history.serial_number=a.serial_number)) AND (a.serial_number=ANY('{}'::text[]::text[]) OR (NOT (a.serial_number=ANY('{}'::text[]::text[])) AND NOT (coalesce(a.product_reference,'')=ANY(ARRAY['176468178','176943497','177972146','177980311','AMP-Lmp','AMP-Rad','AMP-Tor','Appliance_Dlight_AIR','Appliance_Dlight_S200','Appliance_Dlight_T200','Appliance_Dlight_T200R','BIO-Lmp','BIO-Tor','Dlight-24-E24','Dlight-24-Lmp','Dlight-24-PCBA','Dlight-24-Pan','Dlight-32','Dlight-32-E32','Dlight-32-Lmp','Dlight-32-PCBA','Dlight-32-Pan','Dlight-32-Rad','Dlight-32-Tor','EMobility_ZEM_QS72V3000W','FLH-B-Lmp','FLH-B-Pan','FLH-C-Pan','FLH-Dlight-PCBA','FLH-P-Dlight','FLH-P-Dlight-Lmp','FLH-P-Dlight-PCBA','FLH-P-Dlight-Pan','FLH-P-Dlight-Rad','HOTSPOT','LIO-C-BE','LIO-C-E22','LIO-C-E32','LIO-C-Pan','LIO-D-E24','LIO-D-Pan','LUC-C-Pan','LUC-D-Pan','LUCIOLETEST','Lion-RET23','Lion-Spark-32-Bat','Lion-Spark-40-Bat','Lion-Spark-40-E32','M63J13H','N/A','SolarWorxBU','Sun-Spark-Bat','Sun-Spark-Int','Sun-Spark-Lmp','ZEM-MOT']::text[]::text[]))))
